    addCollider(x + 1.4, z - 1.4, .4, .4, b, b + 4.6, 'tower')
    addCollider(x - 1.4, z + 1.4, .4, .4, b, b + 4.6, 'tower')
    addCollider(x + 1.4, z + 1.4, .4, .4, b, b + 4.6, 'tower')
