  boxMesh(g, .105, .115, .3, gunPoly, 0, -.005, .22)
  boxMesh(g, .09, .17, .11, gunDark, 0, -.11, .04, -.24)
  boxMesh(g, .075, .22, .14, gunMetal, 0, -.155, -.2, .1)
