import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 })
await page.waitForTimeout(600)
await page.keyboard.press('KeyM')
await page.waitForTimeout(300)
console.log(await page.evaluate(() => {
  const inp = document.querySelector('[data-modkey="hologram"]')
  const span = inp.nextElementSibling
  inp.checked = true
  inp.dispatchEvent(new Event('change', { bubbles: true }))
  void span.offsetWidth
  const matched = []
  for (const sheet of document.styleSheets) {
    let rules; try { rules = [...sheet.cssRules] } catch { continue }
    const walk = (rs, media) => {
      for (const r of rs) {
        if (r.cssRules) { walk([...r.cssRules], r.conditionText || media); continue }
        if (!r.selectorText) continue
        for (const sel of r.selectorText.split(',')) {
          try { if (span.matches(sel.trim())) matched.push({ sel: sel.trim(), media, css: r.style.cssText }) } catch {}
        }
      }
    }
    walk(rules, '')
  }
  const cs = getComputedStyle(span)
  return { checked: inp.checked, matches: inp.matches(':checked'), bg: cs.backgroundColor, border: cs.borderColor, matched }
}))
await browser.close()

