import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 })
await page.waitForTimeout(600)
await page.keyboard.press('KeyM')
await page.waitForTimeout(300)
console.log(await page.evaluate(() => {
  const inp = document.querySelector('[data-modkey="hologram"]')
  const span = inp.nextElementSibling
  const sheet = document.styleSheets[0]
  const found = []
  const walk = (rs) => {
    for (const r of rs) {
      if (r.selectorText) {
        found.push(r.selectorText)
      } else if (r.cssRules) walk([...r.cssRules])
    }
  }
  walk([...sheet.cssRules])
  const swRules = found.filter(s => s.includes('.switch'))
  inp.checked = true
  void span.offsetWidth
  const before = getComputedStyle(span).backgroundColor
  span.style.background = 'rgb(255, 0, 0)'
  const afterInline = getComputedStyle(span).backgroundColor
  span.style.background = ''
  span.classList.add('test-on')
  return {
    checked: inp.checked, matches: inp.matches(':checked'), before, afterInline,
    swRules,
    inline: span.getAttribute('style'),
    ruleIndex: [...sheet.cssRules].findIndex(r => r.selectorText === '.switch input:checked + span'),
    totalRules: sheet.cssRules.length,
  }
}))
await browser.close()

